output_text:
[
  {
    "id": "must_get_cart",
    "text": "A shopper is obliged to obtain a cart at the beginning of the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {
        "cart_pickup": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    },
    "justification": "The rule refers only to the domain role of a cart and not to any particular cart bay or coordinate."
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper is forbidden from leaving the store without the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule is expressed in terms of the exit action and possession of a cart, so it applies independently of where the exit is located."
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper must not take a cart into a single-file aisle next to shelves.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    },
    "justification": "The rule uses the layout-independent geometric notion of a single-file shelf aisle rather than naming the aisle's coordinates."
  },
  {
    "id": "no_cart_movement_through_single_file_space",
    "text": "A shopper is forbidden from moving a cart through a single-file passage.",
    "abstraction": {
      "state_properties": {
        "single_file_space": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "MOVE",
          "single_file_space"
        ]
      }
    },
    "justification": "The constraint is based on passage width, a property meaningful in any supermarket layout."
  },
  {
    "id": "cart_transfers_only_in_open_areas",
    "text": "A shopper may pick up or put down a cart only in an open cart-compatible area, not inside a shelf aisle.",
    "abstraction": {
      "state_properties": {
        "open_cart_area": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "gt": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cart_pickup": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        },
        "cart_drop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cart_transfer": {
          "pre": {
            "or": [
              "cart_pickup",
              "cart_drop"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_transfer",
          {
            "not": "open_cart_area"
          }
        ]
      }
    },
    "justification": "The rule characterizes suitable cart-transfer places by openness and shelf adjacency rather than by fixed parking-cell coordinates."
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "If a shopper parks or releases the cart during the trip, they are obliged to retrieve a cart before finishing.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {
        "cart_drop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cart_pickup": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_drop",
      "discharge": "cart_pickup"
    },
    "justification": "The norm concerns the social practice of temporarily parking and reclaiming carts, independent of where the parking happens."
  },
  {
    "id": "shelf_interactions_must_be_adjacent_to_shelf",
    "text": "An item-taking interaction is permitted only when the shopper is adjacent to a shelf.",
    "abstraction": {
      "state_properties": {
        "beside_shelf": "adjShelf"
      },
      "events": {
        "item_interaction_with_cart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "item_interaction_on_foot": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "item_interaction": {
          "pre": {
            "or": [
              "item_interaction_with_cart",
              "item_interaction_on_foot"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_interaction",
          {
            "not": "beside_shelf"
          }
        ]
      }
    },
    "justification": "The rule identifies item collection by interaction type and shelf adjacency, not by the coordinates of the item locations."
  },
  {
    "id": "entering_single_file_shelf_aisle_requires_shopping_purpose",
    "text": "When a shopper enters a single-file shelf aisle on foot, they are obliged to perform an item interaction there.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_on_foot": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        },
        "item_interaction_on_foot": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "adjShelf"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enter_single_file_shelf_aisle_on_foot",
      "discharge": "item_interaction_on_foot"
    },
    "justification": "The norm treats narrow shelf aisles as special functional spaces using geometry and shelf adjacency, so it transfers to other floor plans."
  }
]
